function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
const sel = parse(input.sel_body) || {};
const libs = Array.isArray(sel.libraries) ? sel.libraries : [];
const names = [];
for (const l of libs) { const n = String((l && l.library) || '').trim(); if (n && names.indexOf(n) === -1) names.push(n); }
