assemble.code:
function parse(b) { if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return null; } } return b; }
function norm(s) { s = String(s).trim(); try { s = s.normalize('NFKC'); } catch (e) {} return s.toLowerCase(); }
const TOMB = '（舊管線產物';
function usable(e) {
  if (!e || typeof e !== 'object') return false;
  if (!e.page_name) return false;
  const c = String(e.content || '');
  if (!c.trim() || c.indexOf(TOMB) === 0 || c.indexOf('（重複頁') === 0) return false;
  if (e.metadata_json) {
    try {
      const m = JSON.parse(e.metadata_json);
      if (m && m.status === 'deprecated') return false;
      // 🔴 地圖自己產的摘要 block（kind=library_map）不是使用者的原文。
      //   實測（2026-08-17，youlin 真資料）：不濾的話它們會**霸佔出處清單前段**
      //   ——因為它們的內容就是庫名＋核心實體，字面重疊分數天生最高，
      //   於是 `library-map:kb` 這種內部頁名會被當成「參照原文位置」印給使用者看，
      //   而 leo 要的正是「**會看到他的參照原文位置檔名**」。印內部產物＝答非所問。
      //   同一個口徑 kbdb 那側早就有了（liveEntryCountsByLibrary 註解：
      //   「地圖不該把自己算進地圖裡」），只是 GET /entries 是通用列表端點不做這個排除
      //   ⇒ 排除留在讀端。它們的內容並沒有消失：已經以「子庫目錄」的形式在 prompt 最前面。
      if (m && m.kind === 'library_map') return false;
    } catch (err) {}
  }
  return true;
}
function metaOf(e) { if (e && e.metadata_json) { try { return JSON.parse(e.metadata_json) || {}; } catch (err) {} } return {}; }
function srcOf(e) { return String(metaOf(e).source || ''); }
function libOf(e) { return String(metaOf(e).library || 'general'); }
// machineOf（`inkstone/mira#6`）：這則知識的原稿在**哪一台機器**上。
// 回一個「要不要放這兩個 key」的物件：**缺值就一個 key 都不放**，不塞空字串——
// 前端的判準是「有沒有值」，空字串會讓「未知來源」變成一個看起來有名字的東西。
// 舊資料（改版前灌的）本來就沒有這一格，那就是誠實的「未知來源」。
function machineOf(e) {
  const m = metaOf(e);
  const id = String(m.machine || '');
  if (!id) return {};
  const label = String(m.machine_label || '') || id;
  return { machine: id, machine_label: label };
}
// 把 machineOf 的結果併進一個既有物件（三處投影共用一份，不要各寫各的）。
function withMachine(obj, e) {
  const mm = machineOf(e);
  if (mm.machine) { obj.machine = mm.machine; obj.machine_label = mm.machine_label; }
  return obj;
}
function chunkIdx(src) { const m = /#(\d+)$/.exec(src); return m ? parseInt(m[1], 10) : 999; }
function toksOf(text) {
  const t = norm(text);
  const out = new Set();
  for (const w of (t.match(/[a-z0-9]{2,}/g) || [])) out.add(w);
  const cjk = t.replace(/[^一-鿿]/g, ' ');
  for (const seg of cjk.split(/\s+/)) { for (let i = 0; i + 1 < seg.length; i++) out.add(seg.slice(i, i + 2)); }
  return out;
}

const question = String(input.question || '');
const sel = parse(input.sel_body) || {};
const route = String(sel.route || 'all');
const selLibs = Array.isArray(sel.libraries) ? sel.libraries : [];
const indexes = Array.isArray(sel.indexes) ? sel.indexes : [];

// ── 館藏目錄：一律進 prompt（「有哪些子庫、各自談什麼」的答案在這裡）──
let catalog = '';
if (indexes.length) {
  catalog = '本知識庫的子庫目錄（共 ' + indexes.length + ' 個）：\n';
  for (const ix of indexes) {
    const bits = [];
    if (typeof ix.entry_count === 'number') bits.push(ix.entry_count + ' 筆內容');
    if (typeof ix.triplet_count === 'number') bits.push(ix.triplet_count + ' 條關聯');
    // narrative 還沒寫進來的庫，用重點實體代替——不編造，也不留白
    const desc = (ix.narrative && String(ix.narrative).trim())
      ? String(ix.narrative).trim()
      : ((Array.isArray(ix.top_entities) && ix.top_entities.length)
          ? ('主要談：' + ix.top_entities.join('、'))
          : '（這個子庫還沒有內容摘要）');
    catalog += '- ' + ix.library + '（' + bits.join('・') + '）：' + desc + '\n';
  }
  catalog += '\n';
}

// ── 命中子庫與命中實體（graph 的話語）──
let hitTxt = '';
const facts = [];
if (selLibs.length) {
  hitTxt = '這個問題從知識圖譜比對到下列子庫（' +
    (route === 'graph' ? '依三元組實體命中' : '依子庫索引比對') + '）：\n';
  for (const l of selLibs) {
    const ents = Array.isArray(l.matched_entities) ? l.matched_entities : [];
    hitTxt += '- ' + l.library + (ents.length ? '（命中實體：' + ents.join('、') + '）' : '') + '\n';
    for (const e of ents) { const line = e + ' 出現在子庫 ' + l.library; if (facts.indexOf(line) === -1) facts.push(line); }
  }
  hitTxt += '\n';
}

// ── 選中子庫的原文 ──
//
// 🔴 `inkstone/mira#6`（總管 2026-08-18 裁定）：**內容留一份、出處記多台**。
//   leo 的原話就是判準——「就算是我一個人的，我有 2 台電腦、1 台 NAS，
//   **它會告訴我原稿去哪裡找，但知識全在總庫**」：
//     「知識全在總庫」        → 餵給 LLM 的內容去重是對的，留一份
//     「告訴我原稿去哪裡找」  → 出處不能去重，所有持有該原稿的機器都要看得見
//   這本來就是分開的兩層，以前被綁在同一個去重動作上才會互相打架。
//
//   這道去重的鍵是「頁名＋內容」。同一份檔同步到兩台、內容一模一樣時，
//   第二台**整筆**在這裡就被丟掉 ⇒ 它的原稿位置在下游（sources／pages_read）
//   再也長不回來。這是本題三處去重裡最上游的一處，所以下游那兩處各自修好了，
//   送到前端的仍然只有一台——它們拿不到一個已經不存在的東西。
//
//   ⇒ 內容照舊只留一份（同樣的文字餵兩次只是燒掉 8000 字預算），
//     但把「還有哪幾台也持有這一份」記在被留下的那一筆身上，供出處投影使用。
//
//   三條收斂規則（**刻意做成與到達順序無關**——「先到的那一台贏」正是本票在修的病，
//   不可以在修它的時候又引進一個新的順序相依）：
//     ① 說不出機器的那一筆（舊資料）**不會**變成第二個出處——不知道就是不知道，
//        編一個「未知來源」列出來只是製造一列沒有資訊的東西。
//     ② 同一台機器的重複片段不是第二個出處（同一把 machine 只算一次）。
//     ③ 代表那一筆若說不出機器、而後來的說得出 ⇒ **換它當代表**。
//        否則同一份資料會因為 KBDB 回傳順序不同而時而一列、時而兩列。
//   ⇒ **`blocks` 的筆數與改版前完全相同**（一個內容群仍然只留一筆），
//     所以下面的 IDF 統計與頁面排序一個數字都不會變；變的只有出處投影。
const raw = ((parse(input.pages_body) || {}).entries) || [];
const groups = new Map();
const order = [];
for (const e of raw) {
  if (!usable(e)) continue;
  const k = e.page_name + '|' + String(e.content).trim();
  const mk = String(metaOf(e).machine || '');
  const g = groups.get(k);
  if (!g) {
    groups.set(k, { rep: e, extras: [], machines: mk ? [mk] : [] });
    order.push(k);
    continue;
  }
  if (!mk) continue;                                  // ① 說不出是哪一台
  if (g.machines.indexOf(mk) !== -1) continue;        // ② 同一台的重複片段
  if (!g.machines.length) { g.rep = e; g.machines.push(mk); continue; }   // ③ 換代表
  g.machines.push(mk);
  g.extras.push(e);
}
const blocks = [];
const alsoOn = new Map();
for (const k of order) {
  const g = groups.get(k);
  blocks.push(g.rep);
  if (g.extras.length) alsoOn.set(g.rep, g.extras);
}
// 一筆 block 的所有出處＝自己 ＋ 內容一模一樣、被上面併掉的其他機器。
// 回的是**原始 entry**，所以 srcOf／libOf／withMachine 三個既有函式照用，
// 不為了這件事另立第二套投影寫法。
function originsOf(e) { return [e].concat(alsoOn.get(e) || []); }
// 庫內排序（不是檢索）：IDF 字面重疊決定哪幾頁先進預算
const qToks = toksOf(question);
const N = blocks.length || 1;
const df = new Map();
const bToks = [];
for (const e of blocks) { const ts = toksOf(e.content); bToks.push(ts); for (const t of ts) df.set(t, (df.get(t) || 0) + 1); }
const pageScore = new Map();
blocks.forEach(function (e, i) {
  let sc = 0;
  for (const t of qToks) if (bToks[i].has(t)) sc += Math.log(1 + N / (df.get(t) || 1));
  pageScore.set(e.page_name, Math.max(pageScore.get(e.page_name) || 0, sc));
});
const pages = Array.from(new Set(blocks.map(function (e) { return e.page_name; })))
  .sort(function (a, b) { return (pageScore.get(b) || 0) - (pageScore.get(a) || 0); });

// 預算 8000 字，範圍已收斂 ⇒ 可以收下多頁（v3 只敢收 1～2 頁，因為它是從全庫挑）
let budget = 8000;
const ctxBlocks = [];
const pagesRead = [];
for (const page of pages) {
  if (budget <= 0) break;
  const es = blocks.filter(function (e) { return e.page_name === page; });
  es.sort(function (x, y) { return chunkIdx(srcOf(x)) - chunkIdx(srcOf(y)); });
  // 🔴 `inkstone/mira#6`（retrieval-tree-and-breadcrumb 2026-08-18 在 stage 實測抓到）：
  //   這裡原本是「一個 page_name 一筆」、而且拿 es[0] 的 source ⇒ 同一頁同時存在於
  //   兩台機器時，pages_read **只會留下先到的那一台**，另一台的原稿位置就此消失。
  //   那正好抵銷掉本票要做的事（答得出原稿在哪台機器）。
  //   ⇒ 分組鍵改成 (頁, 機器)。沒有 machine 的舊資料一律落在同一組（鍵＝空字串），
  //   行為與改版前一字不差。
  const perMachine = new Map();
  for (const e of es) {
    if (budget <= 0) break;
    let c = String(e.content);
    if (c.length > budget) c = c.slice(0, budget);
    budget -= c.length;
    // `entry` 只在本函式內部用來回查「這份內容還在哪幾台上」（sources 投影要用），
    // 它不會出現在回應裡：ctxBlocks 只被拿來組 ctx 字串與 sources。
    ctxBlocks.push(withMachine({ page: page, content: c, source: srcOf(e), library: libOf(e), entry: e }, e));
    // 內容只算一次預算（上面 budget 已扣），出處則每台各記一筆。
    for (const o of originsOf(e)) {
      const mk = String(metaOf(o).machine || '');
      const g = perMachine.get(mk);
      if (g) { g.chars += c.length; } else { perMachine.set(mk, { chars: c.length, first: o }); }
    }
  }
  for (const g of perMachine.values()) {
    if (g.chars > 0) pagesRead.push(withMachine({ page: page, library: libOf(g.first), chars: g.chars, source: srcOf(g.first) }, g.first));
  }
}

const sources = [];
ctxBlocks.forEach(function (bk, i) {
  // machine 從 ctxBlocks 帶過來（它上面已經 withMachine 過），不重解一次 metadata。
  const out = { n: i + 1, mode: bk.library, page: bk.page, source: bk.source };
  if (bk.machine) { out.machine = bk.machine; out.machine_label = bk.machine_label; }
  sources.push(out);
  // 內容一模一樣、在上游被併掉的其他機器：出處各給一列。
  // 🔴 `n` 沿用同一個編號，**不是漏寫**：它們指的是同一段文字，prompt 裡只出現一次 [n]，
  //   換一個編號會讓 LLM 的引用對不上。前端列出處時不看 n（看 page／source／machine），
  //   引擎那側 `dedupeSourcesByPage` 的鍵是「頁 × 機器」⇒ 這幾列不會被併掉。
  for (const o of (alsoOn.get(bk.entry) || [])) {
    sources.push(withMachine({ n: i + 1, mode: bk.library, page: bk.page, source: srcOf(o) }, o));
  }
});
let ctx = '';
ctxBlocks.forEach(function (bk, i) { ctx += '[' + (i + 1) + '] （出自子庫《' + bk.library + '》的《' + bk.page + '》）\n' + bk.content + '\n\n'; });

const prompt = '你是企業知識庫問答助手。只根據下面提供的資料回答，資料裡沒有的不要編造；' +
  '引用原文時標注資料編號如 [1]、[2]。\n\n' +
  catalog + hitTxt +
  '原文片段：\n' + (ctx || '（這次沒有讀入原文片段——若問題可由上面的子庫目錄回答，就用目錄回答）\n') +
  '\n問題：' + question + '\n\n' +
  '輸出規則（嚴格遵守）：不要輸出思考過程或英文草稿，只輸出一行——' +
  '以【答】開頭、用正體中文、一段話；引用原文時帶 [n]，只用子庫目錄回答時不必帶編號；' +
  '資料不足就寫【答】後接「知識庫裡沒有這方面資料」。';

// 前端契約（console-ui/public/portal/index.html retrievalTraceHtml，b48f02b）
const retrieval = {
  route: route,
  vector_used: false,
  libraries_considered: typeof sel.libraries_considered === 'number' ? sel.libraries_considered : indexes.length,
  libraries: selLibs.map(function (l) {
    return { library: l.library, score: l.score, via: l.via, matched_entities: Array.isArray(l.matched_entities) ? l.matched_entities : [] };
  }),
  indexes_read: indexes.map(function (ix) {
    return {
      library: ix.library, narrative: ix.narrative || '', selected: !!ix.selected,
      top_entities: Array.isArray(ix.top_entities) ? ix.top_entities : [],
      triplet_count: ix.triplet_count, entry_count: ix.entry_count
    };
  }),
  pages_read: pagesRead
};

return { success: true, prompt: prompt, sources: sources, graph_facts: facts, retrieval: retrieval, has_ctx: ctxBlocks.length > 0 };

finalize.code:
const answer = String(input.answer == null ? '' : input.answer).trim();
const rawSources = Array.isArray(input.sources) ? input.sources : [];
const rawFacts = Array.isArray(input.graph_facts) ? input.graph_facts : [];
const rawRetrieval = input.retrieval && typeof input.retrieval === 'object' ? input.retrieval : null;

// 用 match（非 exec）取出這次答案真的引用過的編號，避免依賴 LLM 的措辭。
const cited = new Set();
(answer.match(/\[\d+\]/g) || []).forEach(function (tag) {
  cited.add(parseInt(tag.slice(1, -1), 10));
});

const sources = cited.size ? rawSources.filter(function (s) { return s && cited.has(s.n); }) : [];
const hit = sources.length > 0;

let retrieval = null;
if (hit && rawRetrieval) {
  // sources 的 mode 欄位存的就是 library 名（assemble 的投影：{ n, mode: bk.library, page, source }）。
  const citedLibs = new Set(sources.map(function (s) { return s.mode; }).filter(Boolean));
  // pages_read 是「按頁＋機器聚合」的一列（assemble 的 perMachine 分組），
  // 而 sources 是「按片段（chunk）」的一列——同一頁常常有好幾個片段、各自不同的
  // source URI（#0／#3…）。拿片段的 source 字面去比對頁級的代表 source 一定對不上
  // （代表片段不保證是被引用的那一段）。真正共通的鍵是「頁名＋機器」，兩邊都有。
  const citedPageKeys = new Set(sources.map(function (s) {
    return String(s.page || '') + '|' + String(s.machine || '');
  }));
  retrieval = Object.assign({}, rawRetrieval, {
    libraries: (Array.isArray(rawRetrieval.libraries) ? rawRetrieval.libraries : [])
      .filter(function (l) { return l && citedLibs.has(l.library); }),
    indexes_read: (Array.isArray(rawRetrieval.indexes_read) ? rawRetrieval.indexes_read : [])
      .filter(function (ix) { return ix && citedLibs.has(ix.library); }),
    pages_read: (Array.isArray(rawRetrieval.pages_read) ? rawRetrieval.pages_read : [])
      .filter(function (p) { return p && citedPageKeys.has(String(p.page || '') + '|' + String(p.machine || '')); })
  });
}

return {
  success: true,
  answer: answer || '（知識庫裡沒有找到足以回答的資料。）',
  sources: sources,
  // 三元組摘要跟出處同命運：沒有真的用上任何一筆原文，這些「參考事實」
  // 也只是陪葬的內部資訊，一併清空。
  graph_facts: hit ? rawFacts : [],
  retrieval: retrieval
};

prep.code:
// 入口驗證（inkstone/arcrun-rag#13 c15014 第 1 條）：呼叫端沒帶 page_name 時，模板引擎把
// 字面的 `{{input.page_name}}` 原樣塞進來（graph-executor interpolateString），對 `||` 是 truthy，
// 舊寫法因此把那串字面文字當成真的頁名寫進知識庫。prep 是整張卡進 KBDB 前的第一個節點，在這裡擋。
// code 零件只有 throw 才算節點失敗；return {success:false} 會被沙箱包成成功信封照樣往下走（c15011）。
function isUnresolvedTemplate(v) {
  return typeof v === 'string' && /^\{\{[\w.]+\}\}$/.test(v);
}
const rawPageName = input.page_name;
if (rawPageName == null || String(rawPageName).trim() === '' || isUnresolvedTemplate(rawPageName)) {
  throw new Error('page_name 缺失或未代入（收到 ' + JSON.stringify(rawPageName) + '）——拒絕寫入知識庫');
}
const pageName = String(rawPageName);
// 🔴 c15345（總管實測抓到的真 bug）：呼叫端沒帶 path 時，同一個 `isUnresolvedTemplate`
// 沒套在這一格——`input.path || (pageName + '.md')` 對字面 `{{input.path}}` 也是
// truthy，跟 page_name 那次 c15014 撞過的病一模一樣，只是這次是 path 這格。
// 修法：套同一個檢查，未代入就退回 `pageName + '.md'`，不讓字面模板字串流進
// source_path／source_uri，寫進 KBDB 給使用者看到的原稿路徑。
const rawPath = input.path;
